@Component("building-entity-projector")
public class BuildingEntityProjector implements EntityProjector<Building>{
		
	// core constructor
	public BuildingEntityProjector(ProjectorRegistry registry,
										BuildingRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Building> getEntityClass() {
		return Building.class;
	}

    /*
	 * Insert a Building
	 * 
     * @param	entity Building
     */
    public Building create( Building entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Building
	 * 
     * @param	entity Building
     */
    public Building update( Building entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Building
	 * 
     * @param	id		UUID
     */
    public Building delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Building entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Site
     * 
     * @param	parentId	UUID
     * @param	assignment 	Site 
     * @return	Building
     */
    public Building assignSite( UUID parentId, Site assignment ) {
	    LOGGER.info("assigning Site as " + assignment.toString() );

	    Building parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Site.class, assignment.getSiteId());

	    // ------------------------------------------
		// assign the Site to the parent entity
		// ------------------------------------------ 
	    parentEntity.setSite( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Site
	 * 
	 * @param	parentId		UUID
	 * @return	Building
	 */
	public Building unAssignSite( UUID parentId ) {
		Building parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Site on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Site on the parent entithy
		// ------------------------------------------     
	    parentEntity.setSite(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Floors
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Building
     */
    public Building addToFloors( UUID parentId, Floor addTo ) {
	    LOGGER.info("handling AssignFloorsToBuildingEvent - " );
	    
	    Building parentEntity = repository.findById(parentId).get();
	    Floor child = registry.project( Floor.class, addTo.getFloorId());
	    
	    parentEntity.getFloors().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Floors
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Building
     */
	public Building removeFromFloors( UUID parentId, Floor removeFrom ) {
	    LOGGER.info("handling RemoveFloorsFromBuildingEvent " );
	
	    Building parentEntity = repository.findById(parentId).get();
	    Floor child = registry.project( Floor.class, removeFrom.getFloorId());
	    
	    parentEntity.getFloors().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Building via an FindBuildingQuery
     * @return 	query	FindBuildingQuery
     */
    @SuppressWarnings("unused")
    public Building find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Building - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Buildings
     *
     * @param	query	FindAllBuildingQuery 
     * @return 	List<Building> 
     */
    @SuppressWarnings("unused")
    public List<Building> findAll( FindAllBuildingQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Building - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final BuildingRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(BuildingEntityProjector.class.getName());

}
